function readMinutes(a){return Math.max(1,Math.round(String(a.body||'').length/500))}
function magazineCards(){return '<div class="article-grid">'+articles().map((a,i)=>`<a class="collection article-card" href="#article/${E(a.id)}"><span class="article-cover brand-art tone-${[0,2,3][i%3]}" aria-hidden="true"><span class="article-no">${String(i+1).padStart(2,'0')}</span>${I('arch','article-mark')}</span><span class="article-text"><span class="article-meta">${E(a.author||t('shell.brand'))}${a.published_at?' · '+E(a.published_at.slice(0,10)):''} · ${E(t('article.minutes',{n:readMinutes(a)}))}</span><h3>${E(a.title)}</h3>${a.summary?`<p>${E(a.summary)}</p>`:''}<span class="text-link">${E(t('article.read'))}${I('caret-right')}</span></span></a>`).join('')+'</div>'}

function articlePage(id){const a=articles().find(x=>x.id===id);return a?`<article class="article"><header class="article-head"><p class="eyebrow">빛의 건축 읽기</p><h1>${E(a.title)}</h1>${a.summary?`<p class="article-dek">${E(a.summary)}</p>`:''}<p class="article-byline"><span class="byline-mark" aria-hidden="true">${I('arch')}</span><span>${E(a.author||'빛의 건축')}${a.published_at?' · '+E(a.published_at.slice(0,10)):''} · ${readMinutes(a)}분 읽기</span></p></header><div class="record-note article-body">${E(a.body)}</div>${a.source_url?`<p class="article-source">${link(a.source_url,'원문·출처 보기')}</p>`:''}<div class="article-foot"><a class="button tonal" href="#magazine">${I('book-open-text')}다른 글 보기</a><a class="button subtle" href="#routes">${I('path')}에디터 코스</a></div></article>`:notFound()}

function detail(p){if(!p)return notFound();if(isSynced(p))return syncedDetail(p);if(isArchive(p))return archiveDetail(p);const f=C.freshness(p),id=E(p.place_id),gallery=mediaFor(p),mapURL=mapLinkFor(p),c=C.coords(p),sim=similarSection(p),en=uiLang()==='en';return `<div class="detail">${detailHero(p)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E(category(p))}${p.district?' · '+E(p.district):''}</p><h1>${E(nm(p))}</h1>${en?(p.name_kr&&p.name_kr!==nm(p)?`<p class="detail-sub" lang="ko">${E(p.name_kr)}</p>`:''):p.name_en?`<p class="detail-sub">${E(p.name_en)}</p>`:''}<div class="detail-pills">${badge(p)}${p.free===true?`<span class="pill">${E(t('filter.free'))}</span>`:''}${p.indoor===true?`<span class="pill">${E(t('filter.indoor'))}</span>`:p.indoor===false?`<span class="pill">${E(t('detail.outdoor'))}</span>`:''}</div></header>${quickActions(p,mapURL)}${sectionTabs(!!sim,!!(p.short_description||p.why_it_matters))}${p.short_description||p.why_it_matters?`<div class="detail-lead" id="detailAbout"${en?' lang="ko"':''}>${p.short_description?`<p class="detail-description">${E(p.short_description)}</p>`:''}${p.why_it_matters?`<p class="quote">${E(p.why_it_matters)}</p>`:''}</div>`:''}<aside class="detail-aside" id="detailInfo"><div class="info-card"><h2>${E(t('detail.beforeVisit'))}</h2><dl class="kv-list"><div class="kv"><dt>${E(t('field.address'))}</dt><dd>${E(p.address||t('detail.noAddress'))}</dd></div><div class="kv"><dt>${E(t('detail.hours'))}</dt><dd>${E(p.current_hours_verified||p.typical_hours||t('detail.checkNeeded'))}${p.recommended_time?`<small>${E(t('detail.bestTime',{v:p.recommended_time}))}</small>`:''}</dd></div><div class="kv"><dt>${E(t('detail.fee'))}</dt><dd>${E(p.free===true?t('detail.feeFree'):p.free===false?t('detail.feePaid'):t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('detail.checked'))}</dt><dd>${E(p.verified_at||t('detail.none'))}${f.age!==null?' · '+E(t('detail.daysAgo',{n:f.age})):''}</dd></div><div class="kv"><dt>${E(t('project.coords'))}</dt><dd>${c?E(c.join(', '))+' · '+E(t('detail.coordsSource')):E(t('detail.noCoordsCurated'))}</dd></div></dl><div class="notice warning">${I('warning')}<span>${E(statusLabel(f))}. ${E(t('detail.visitWarning'))}</span></div><div class="info-actions"><button class="button large" data-add-route="${id}">${I('plus')}${E(t('detail.addCourse'))}</button>${link(mapURL,t('detail.searchAddress'),'button subtle large')}</div></div>${dataStatus(p)}</aside><div class="detail-main"><section class="detail-section"><h2>${E(t('detail.essay'))}</h2><p class="reading"${en?' lang="ko"':''}>${E(p.expert_description||p.description||t('detail.noEssay'))}</p></section><section class="detail-section" id="detailPhotos"><h2>${E(t('photos.title'))}</h2>${gallery.length?`<div class="image-gallery">${gallery.map(m=>figureHTML(p,m)).join('')}</div>`:''}<p class="section-note">${E(t('photos.curatedNote'))} <a href="./support.html">${E(t('photos.report'))}</a></p><button class="button subtle" data-load-photo="${id}">${I('images')}${E(t('photos.candidates'))}</button><div id="photoResult"></div></section><section class="detail-section"><h2>${E(t('detail.programme'))}</h2><p class="program-name"${en?' lang="ko"':''}>${E(p.current_program||t('detail.noProgramme'))}</p>${p.program_start||p.program_end?`<p class="section-note tnum">${E(p.program_start||'')}${p.program_end?' – '+E(p.program_end):''}</p>`:''}${p.verification_note?`<p class="section-note"${en?' lang="ko"':''}>${E(p.verification_note)}</p>`:''}</section>${archiveSections(p)}${liveInfo(p)}${visitsSection(p)}</div></div>${sim}</div>${actionBar(p,mapURL)}</div>`}

// ===== Archive sections of a place page (docs/ARCHIVE_SPEC.md §6): the same for curated places, Wikidata items and
// archive projects. Values carry their field state; a field without a value is listed apart as 미확인.
function creditsOf(p){const own=Array.isArray(p.credits)?p.credits:[];return own.length?own:LEGACY_CREDITS.filter(([k])=>p[k]).map(([k,role])=>({role,name:p[k]}))}
function roleLabel(r){return r==='creator'?t('role.creator'):vlabel('credit_role',r)}
function listLabels(name,v){return Array.isArray(v)?v.map(x=>vlabel(name,x)).join(', '):typeof v==='string'?v:''}
// [display value, its field state]; '' = unknown. Curated values have no per-field state (the record is editorial).
function fieldValue(p,k){const L=uiLang(),num=(v,u)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString(L==='en'?'en-US':'ko-KR')+u:'';switch(k){
 case 'name_original':return p.name_original||'';case 'name_en':return p.name_en||'';case 'name_ko':return p.name_ko||(!isSynced(p)&&!isArchive(p)?p.name_kr:'')||'';
 case 'country_iso2':{const r=X.region(p);return r.iso?countryName(r.iso):r.country||''}
 case 'city':return cityName(X.region(p).cityKey);case 'address':return p.address||'';
 case 'project_type':return vlabel('project_type',X.typeOf(p));case 'operating_status':case 'installation_method':case 'envelope_type':return vlabel(k,p[k]);
 case 'technology':return listLabels('technology',p.technologies||p.technology);case 'content_type':return listLabels('content_type',p.content_types);case 'spatial_context':return listLabels('spatial_context',p.spatial_context);
 case 'credits':return creditsOf(p).map(c=>roleLabel(c.role)+': '+(L==='en'&&c.name_en||c.name)).join(' · ');
 case 'display_area_m2':return num(p.display_area_m2,' ㎡');case 'pixel_pitch_mm':return num(p.pixel_pitch_mm,' mm');
 case 'interactive':return p.interactive===true?t('common.yes'):p.interactive===false?t('common.no'):'';
 default:{const v=p[k];return v===null||v===undefined?'':String(v)}}}
function fieldState(p,k){const s=p.field_status?.[k]?.state;if(s)return s;if(k==='project_type'&&X.typeDerived(p))return 'derived';return isArchive(p)||isSynced(p)?'unverified':null}
function stateBadge(st){return st?`<span class="state-badge state-${E(st)}">${E(st==='unverified'?t('state.unverifiedValue'):vlabel('field_state',st))}</span>`:''}
function archiveInfo(p){const groups=Object.entries(T.fields).map(([g,keys])=>[g,keys.map(k=>[k,fieldValue(p,k)])]),unknown=groups.flatMap(([,rows])=>rows.filter(r=>!r[1]).map(r=>r[0])),extra=!isArchive(p)&&!isSynced(p)&&p.project_year?`<div class="kv"><dt>${E(t('field.project_year'))}</dt><dd>${E(p.project_year)}</dd></div>`:'';
 return `<section class="detail-section archive-info" id="detailArchive"><h2>${E(t('archive.title'))}</h2>${groups.map(([g,rows])=>{const known=rows.filter(r=>r[1]);return known.length||g==='basic'&&extra?`<div class="field-group"><h3>${E(T.groupLabels[g][uiLang()==='en'?1:0])}</h3><dl class="kv-list">${known.map(([k,v])=>`<div class="kv"><dt>${E(T.fieldLabel(k,uiLang()))}</dt><dd><bdi${k==='name_original'&&p.name_original_lang?` lang="${E(p.name_original_lang)}"`:''}>${E(v)}</bdi>${stateBadge(fieldState(p,k))}</dd></div>`).join('')}${g==='basic'?extra:''}</dl></div>`:''}).join('')}${unknown.length?`<details class="unknown-fields"><summary>${E(t('archive.unknown',{n:unknown.length}))}</summary><p class="section-note">${E(t('archive.unknownNote'))}</p><ul>${unknown.map(k=>`<li>${E(T.fieldLabel(k,uiLang()))}</li>`).join('')}</ul></details>`:''}<p class="section-note">${E(t('archive.stateNote'))}</p></section>`}
// Sources: publisher, kind, licence, dates, link state, reliability and the fields each one supports.
function tier(r){return typeof r!=='number'?null:r>=80?'high':r>=55?'medium':'low'}
function shortDate(v){return v?String(v).slice(0,10):''}
function sourcesOf(p){if(isArchive(p)||p.archive_place_id&&Array.isArray(p.sources)&&p.sources.length)return p.sources||[];if(isSynced(p)){const q=p.wikidata||p.place_id.slice(3);return [{title:'Wikidata '+q,url:'https://www.wikidata.org/wiki/'+q,publisher:'Wikidata',kind:'wikidata',license:'CC0 1.0',retrieved_at:window.AOL_GLOBAL?.fetchedAt||null,last_checked_at:null,link_state:'unknown',reliability:70,supports:Object.keys(p.field_status||{}).concat(['name_original','latitude','longitude'])}]}const seen=new Set();return [...D.sources.filter(s=>s.place_id===p.place_id).map(s=>({title:s.title,url:s.url,publisher:s.publisher,kind:null,license:null,retrieved_at:null,last_checked_at:s.checked_date||null,link_state:'unknown',reliability:null,supports:[]})),...[[p.verification_source_1,'official'],[p.verification_source_2,null],[p.source_url,null]].filter(([u])=>u).map(([u])=>({title:null,url:u,publisher:p.source_publisher||null,kind:null,license:null,retrieved_at:null,last_checked_at:p.verified_at||null,link_state:'unknown',reliability:null,supports:[]}))].filter(s=>{const u=C.safeURL(s.url);if(!u||seen.has(u))return false;seen.add(u);return true})}
function sourcesSection(p){const list=sourcesOf(p);return `<section class="detail-section" id="detailSources"><h2>${E(t('sources.title'))}</h2>${list.length?`<ol class="source-list">${list.map(sr=>{const u=C.safeURL(sr.url),host=(()=>{try{return new URL(u).host.replace(/^www\./,'')}catch{return ''}})(),broken=sr.link_state==='broken',tr=tier(sr.reliability),meta=[[t('sources.license'),sr.license||t('sources.noLicense')],[t('sources.retrieved'),shortDate(sr.retrieved_at)],[t('sources.checked'),[shortDate(sr.last_checked_at),vlabel('link_state',sr.link_state)].filter(Boolean).join(' · ')],[t('sources.supports'),(sr.supports||[]).filter((k,i,a)=>a.indexOf(k)===i).map(k=>T.fieldLabel(k,uiLang())).join(', ')]].filter(r=>r[1]);return `<li class="source-item${broken?' broken':''}"><div class="source-head"><b>${E(sr.publisher||host||sr.title||'')}</b>${sr.kind?`<span class="pill">${E(vlabel('source_kind',sr.kind))}</span>`:''}${tr?`<span class="pill tier-${tr}">${E(t('sources.tier.'+tr,{n:sr.reliability}))}</span>`:''}</div>${sr.title&&sr.title!==sr.publisher?`<p class="source-title">${E(sr.title)}</p>`:''}<dl class="source-meta">${meta.map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl>${broken?`<p class="link-broken">${I('link-break','icon-sm')}${E(t('sources.broken'))}${host?' · '+E(host):''}</p>`:u?link(u,host||t('sources.open')):''}</li>`}).join('')}</ol>`:`<p class="section-empty">${E(t('sources.none'))}</p>`}${list.some(x=>typeof x.reliability==='number')?`<p class="section-note">${E(t('sources.note'))}</p>`:''}</section>`}
// Record origin, review state, collection and verification times, update state, in plain words.
function originLabel(p){const o=X.originOf(p);return o==='curated'?t('origin.curated'):o==='editor_verified'?t('origin.verified'):isSynced(p)||p.origin==='wikidata'?t('origin.wikidata'):t('origin.auto')}
function dataStatus(p){const a=isArchive(p),sy=isSynced(p),cur=!a&&!sy&&p.origin!=='wikidata',o=X.originOf(p),f=C.freshness(p),rec=a&&p.record_origin?vlabel('record_origin',p.record_origin):cur?t('origin.curated'):sy||p.origin==='wikidata'?t('origin.wikidataRecord'):vlabel('record_origin','auto_collected'),rows=[[t('status.origin'),`<span class="pill ${o==='unreviewed'?'warn':'ok'}">${E(rec)}</span>`],[t('status.review'),E(a||p.archive_place_id?vlabel('review_status',p.review_status||'unreviewed'):cur?t('status.curatedReview'):vlabel('review_status','unreviewed'))],[t('status.collected'),E(a||p.archive_place_id?syncTimeOr(p.last_collected_at):sy?syncTimeOr(window.AOL_GLOBAL?.fetchedAt):t('status.notCollected'))],[t('status.verified'),E(p.last_verified_at?syncTime(p.last_verified_at):cur&&p.verified_at?p.verified_at:t('status.never'))],[t('status.update'),E(p.update_status?vlabel('update_status',p.update_status):cur?statusLabel(f):a?t('status.current'):t('status.auto6h'))]];
 return `<div class="info-card data-status" id="detailStatus"><h2>${E(t('status.title'))}</h2><dl class="kv-list">${rows.map(([k,v])=>`<div class="kv"><dt>${E(k)}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="status-note">${E(t(o==='unreviewed'?'status.noteAuto':o==='editor_verified'?'status.noteVerified':'status.noteCurated'))}</p>${a||sy?`<p class="status-note">${E(t('status.refresh'))}</p>`:''}</div>`}
function syncTimeOr(v){return v?syncTime(v):t('status.never')}
function statusLabel(f){return t('fresh.'+f.key)===('fresh.'+f.key)?f.label:t('fresh.'+f.key)}
// Researcher assessments: interpretation, kept apart from the collected data and labelled as such.
function assessmentsSection(p){const list=Array.isArray(p.assessments)?p.assessments:[];if(!list.length)return '';return `<section class="detail-section assessments" id="detailAssess"><h2>${E(t('assess.title'))}</h2><p class="assess-label">${I('seal-question','icon-sm')}${E(t('assess.label'))}</p><ul class="assess-list">${list.map(a=>`<li class="assess-item"><div class="assess-head"><b>${E(String(a.attribute).replace(/_/g,' '))}</b>${a.confidence?`<span class="pill info">${E(t('assess.confidence.'+a.confidence))}</span>`:''}</div><p class="assess-value">${E(a.value)}</p>${a.method?`<p class="assess-meta">${E(t('assess.method'))}: ${E(a.method)}</p>`:''}${a.note?`<p class="assess-note">${E(a.note)}</p>`:''}${a.created_at?`<p class="assess-meta">${E(shortDate(a.created_at))}</p>`:''}</li>`).join('')}</ul></section>`}
// Citation: name, record status, the stable record URL and today's access date.
function recordURL(p){let base=window.AOL_CONFIG?.PUBLIC_URL;if(!base)try{base=new URL('.',location.href).href}catch{base=''}return String(base).replace(/\/+$/,'')+'/#place/'+encodeURIComponent(p.place_id)}
function citation(p){return t('cite.text',{name:nm(p),status:originLabel(p),url:recordURL(p),date:C.today()})}
function citationSection(p){return `<section class="detail-section" id="detailCite"><h2>${E(t('cite.title'))}</h2><blockquote class="citation" id="citationText">${E(citation(p))}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-citation="${E(p.place_id)}">${I('copy')}${E(t('cite.copy'))}</button></div><p class="section-note">${E(t('cite.note'))}</p></section>`}
// Similar projects with the reasons they are similar.
function reasonText([k,v]){return k==='technology'?t('why.technology',{v:v.map(x=>vlabel('technology',x)).join(', ')}):k==='decade'?t('why.decade',{v}):k==='category'?t('why.category',{v:category({primary_category:v})}):t('why.'+k,{v:vlabel(k==='type'?'project_type':k==='method'?'installation_method':k==='envelope'?'envelope_type':'region',v)})}
function similarSection(p){const list=X.similar(p,allPlaces());if(!list.length)return '';return `<section class="home-section similar" id="detailRelated"><div class="section-head"><div><h2>${E(t('similar.title'))}</h2><small>${E(t('similar.sub'))}</small></div></div><div class="similar-list">${list.map(({place:x,reasons})=>`<a class="similar-item" href="#place/${E(x.place_id)}"><span class="row-art brand-art" aria-hidden="true">${I(catIcon(x))}</span><span class="similar-text"><b>${E(nm(x))}</b><small>${E([category(x),regionText(x)].filter(Boolean).join(' · '))}</small><span class="similar-why">${reasons.map(r=>`<span>${E(reasonText(r))}</span>`).join('')}</span></span>${I('caret-right','row-chev')}</a>`).join('')}</div></section>`}
function archiveSections(p){return archiveInfo(p)+sourcesSection(p)+assessmentsSection(p)+citationSection(p)}
// An archive project: what the archive publishes, with its sources and states; no hours, fees or programmes.
function archiveDetail(p){const id=E(p.place_id),c=C.coords(p),kind=X.coordKind(p),osm=c&&kind?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:'',gallery=mediaFor(p),summary=uiLang()==='en'?p.summary_en||p.summary_ko:p.summary_ko||p.summary_en,orig=p.name_original&&p.name_original!==nm(p),year=X.yearOf(p),web=C.safeURL(p.official_url||p.website),broken=p.update_status==='link_broken';
 return `<div class="detail archive-detail">${detailHero(p)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E(category(p))}${regionText(p)?' · '+E(regionText(p)):''}</p><h1><bdi>${E(nm(p))}</bdi></h1>${orig?`<p class="detail-sub"><bdi lang="${E(p.name_original_lang||'')}">${E(p.name_original)}</bdi></p>`:p.name_en&&p.name_en!==nm(p)?`<p class="detail-sub">${E(p.name_en)}</p>`:''}<div class="detail-pills">${badge(p)}${year?`<span class="pill">${year}</span>`:''}</div></header>${quickActions(p,osm)}${sectionTabs(true,!!summary,true)}${summary?`<div class="detail-lead" id="detailAbout"><p class="detail-description">${E(summary)}</p></div>`:''}<aside class="detail-aside" id="detailInfo"><div class="info-card archive-card"><h2>${E(t('project.title'))}</h2><dl class="kv-list"><div class="kv"><dt>${E(t('facet.project_type'))}</dt><dd>${E(vlabel('project_type',X.typeOf(p))||t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('project.where'))}</dt><dd>${E(regionText(p)||t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('filter.years'))}</dt><dd>${E(year||t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('facet.operating_status'))}</dt><dd>${E(vlabel('operating_status',p.operating_status)||t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('project.coords'))}</dt><dd>${c&&kind?`<span class="tnum">${E(c[0].toFixed(5)+', '+c[1].toFixed(5))}</span> · ${E(t('coord.'+kind))}${link(osm,t('project.osm'))}`:E(t('project.noCoords'))}</dd></div><div class="kv"><dt>${E(t('project.website'))}</dt><dd>${web?broken?`${E(t('sources.broken'))}`:link(web,t('project.open')):E(t('common.unknown'))}</dd></div>${p.wikidata?`<div class="kv"><dt>Wikidata</dt><dd>${link('https://www.wikidata.org/wiki/'+p.wikidata,'Wikidata '+p.wikidata)}</dd></div>`:''}</dl><div class="info-actions"><button class="button large" data-add-route="${id}">${I('plus')}${E(t('detail.addCourse'))}</button></div></div>${dataStatus(p)}</aside><div class="detail-main">${archiveInfo(p)}<section class="detail-section" id="detailPhotos"><h2>${E(t('photos.title'))}</h2>${gallery.length?`<div class="image-gallery">${gallery.map(m=>figureHTML(p,m)).join('')}</div>`:`<p class="section-note">${E(t('photos.none'))}</p>`}<p class="section-note">${E(t('photos.archiveNote'))} <a href="./support.html">${E(t('photos.report'))}</a></p></section>${sourcesSection(p)}${assessmentsSection(p)}${citationSection(p)}${visitsSection(p)}</div></div>${similarSection(p)}</div>${actionBar(p,osm)}</div>`}
// ===== Research data page (#data): statistics of the current filtered set, its export and the methodology. =====
// One series per chart: bars in one accent (--chart-bar), the value at each bar's tip, unknowns counted apart.
function barChart(id,title,rows,label,{note='',total=0,unknown=0,limit=0}={}){const max=Math.max(1,...rows.map(r=>r[1])),shown=limit?rows.slice(0,limit):rows,rest=rows.length-shown.length;return `<figure class="chart" id="${id}"><figcaption><h3>${E(title)}</h3><small>${E([note,unknown?t('data.unknownCount',{n:fmt(unknown)}):'',rest?t('data.more',{n:fmt(rest)}):''].filter(Boolean).join(' · '))}</small></figcaption>${shown.length?`<ol class="bars" aria-label="${E(title)}">${shown.map(([k,n])=>`<li><span class="bar-label">${E(label(k))}</span><span class="bar-track" aria-hidden="true"><span class="bar" style="width:${Math.max(1.5,n/max*100).toFixed(1)}%"></span></span><span class="bar-value">${fmt(n)}</span></li>`).join('')}</ol>`:`<p class="section-empty">${E(t('data.noValues'))}</p>`}</figure>`}
function exportFilters(){const out={};if(scope!=='all')out.scope=scope;for(const [k,v] of Object.entries(filters)){if(k==='sort'||v===''||v===false||v===null||v===undefined||Array.isArray(v)&&!v.length||(k==='category'||k==='district')&&v==='전체')continue;out[k]=v}return out}
function datasetCitation(n){return t('data.citeText',{n:fmt(n),date:C.today(),url:String(window.AOL_CONFIG?.PUBLIC_URL||'').replace(/\/+$/,'')+'/#data'})}
function exportCtx(ps){return {lang:uiLang(),recordURL,syncedAt:window.AOL_GLOBAL?.fetchedAt||'',filters:exportFilters(),version:APP_VERSION,citation:datasetCitation(ps.length)}}
function exportArchive(kind){const ps=results(),stem=(uiLang()==='en'?'architecture-of-light-archive_':'빛의건축_아카이브_')+C.today(),ctx=exportCtx(ps);if(kind==='csv')download(stem+'.csv',X.exportCSV(ps,ctx),'text/csv;charset=utf-8');else download(stem+'.json',JSON.stringify(X.exportJSON(ps,{...ctx,now:new Date().toISOString()}),null,2),'application/json');toast(t('data.exported',{n:fmt(ps.length)}))}
function dataPage(){const ps=results(),st=X.stats(ps),L=uiLang(),o=Object.fromEntries(st.origin.rows),onMap=ps.filter(X.mappable).length,photos=ps.filter(p=>mediaFor(p).length).length,lab=name=>k=>vlabel(name,k),states=T.vocab.field_state;
 return `<header class="page-head"><h1 class="large-title">${E(t('data.title'))}</h1><p class="page-sub">${E(t('data.sub'))}</p></header><section class="data-scope"><p class="data-scope-line"><b>${E(whereLabel())}</b> · ${E(t('results.count',{n:fmt(ps.length)}))}</p>${activeChips()}<a class="text-link" href="#explore">${I('sliders-horizontal')}${E(t('data.changeFilters'))}${I('caret-right')}</a></section><div class="stat-strip data-stats">${[[ps.length,t('data.total')],[o.curated||0,t('origin.curated')],[o.editor_verified||0,t('origin.verified')],[o.unreviewed||0,t('origin.auto')],[onMap,t('data.onMap')],[photos,t('data.withPhoto')]].map(([n,l])=>`<div class="stat"><b>${fmt(n)}</b><span>${E(l)}</span></div>`).join('')}</div>
 <section class="data-section" aria-labelledby="statsTitle"><div class="section-head"><div><h2 id="statsTitle">${E(t('data.stats'))}</h2><small>${E(t('data.statsSub'))}</small></div></div><div class="chart-grid">${barChart('chartRegion',t('facet.region'),st.region.rows,lab('region'),st.region)}${barChart('chartCountry',t('data.countryTop'),st.country.rows,countryName,{...st.country,limit:20})}${barChart('chartDecade',t('data.decade'),st.decade.rows,k=>t('data.decadeLabel',{v:k}),{...st.decade,note:t('data.yearNote')})}${barChart('chartType',t('facet.project_type'),st.project_type.rows,lab('project_type'),st.project_type)}${barChart('chartMethod',t('facet.installation_method'),st.installation_method.rows,lab('installation_method'),st.installation_method)}${barChart('chartTech',t('facet.technology'),st.technology.rows,lab('technology'),{...st.technology,note:t('data.multiNote')})}${barChart('chartOrigin',t('data.review'),st.origin.rows,k=>(X.ORIGINS.find(x=>x[0]===k)||[])[L==='en'?2:1]||k,st.origin)}</div>${st.year.rows.length?`<details class="year-details"><summary>${E(t('data.byYear'))}</summary>${barChart('chartYear',t('data.byYear'),st.year.rows,k=>String(k),st.year)}</details>`:''}</section>
 <section class="data-section" id="dataExport" aria-labelledby="exportTitle"><h2 id="exportTitle">${E(t('data.export'))}</h2><p class="section-note">${E(t('data.exportSub',{n:fmt(ps.length)}))}</p><p class="notice warning">${I('warning')}<span>${E(X.WARNING[L])}</span></p><div class="actions export-actions"><button type="button" class="button" data-export="csv">${I('download-simple')}${E(t('data.csv'))}</button><button type="button" class="button tonal" data-export="json">${I('download-simple')}${E(t('data.json'))}</button></div><p class="section-note">${E(t('data.exportFormat'))}</p><details class="research-details dictionary"><summary>${E(t('data.dictionary'))}</summary><div class="table-scroll"><table class="dict-table"><thead><tr><th scope="col">${E(t('data.field'))}</th><th scope="col">${E(t('data.type'))}</th><th scope="col">${E(t('data.description'))}</th></tr></thead><tbody>${X.EXPORT_FIELDS.map(([f,ty,ko,en])=>`<tr><td><code>${E(f)}</code></td><td>${E(ty)}</td><td>${E(L==='en'?en:ko)}</td></tr>`).join('')}</tbody></table></div></details><h3 class="licence-title" id="licenceTitle">${E(t('data.licTitle'))}</h3><dl class="kv-list licence-list" aria-labelledby="licenceTitle"><div class="kv"><dt>Wikidata</dt><dd>${E(t('data.licWikidata'))}</dd></div><div class="kv"><dt>Wikimedia Commons</dt><dd>${E(t('data.licCommons'))}</dd></div><div class="kv"><dt>${E(t('data.licEditorialLabel'))}</dt><dd>${E(t('data.licEditorial'))}</dd></div><div class="kv"><dt>${E(t('tab.sources'))}</dt><dd>${E(t('data.licSources'))}</dd></div></dl></section>
 <section class="data-section methodology" id="methodology" aria-labelledby="methodTitle"><h2 id="methodTitle">${E(t('data.method'))}</h2>${[['m.sources','m.sourcesText'],['m.cadence','m.cadenceText'],['m.classify','m.classifyText'],['m.review','m.reviewText']].map(([h,b])=>`<h3>${E(t(h))}</h3><p>${E(t(b))}</p>`).join('')}<h3>${E(t('m.states'))}</h3><dl class="state-list">${states.map(([k])=>`<div><dt>${stateBadge(k)}</dt><dd>${E(t('m.state.'+k))}</dd></div>`).join('')}</dl><h3>${E(t('legend.rule'))}</h3><p>${E(t('legend.ruleText'))}</p><h3>${E(t('m.cite'))}</h3><p>${E(t('m.citeText'))}</p><blockquote class="citation" id="datasetCitation">${E(datasetCitation(ps.length))}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-dataset>${I('copy')}${E(t('cite.copy'))}</button></div></section>`}
function figureHTML(p,m){return `<figure class="gallery-figure"><a class="gallery-photo" href="${E(mediaURL(m))}" target="_blank" rel="noopener noreferrer"><img class="photo" src="${E(mediaURL(m))}" alt="${E(nm(p))}" loading="lazy" data-place-photo data-original="${E(C.safeURL(m.original_file_url))}"></a><figcaption><b class="credit-line">© ${E(m.creator||t('photo.authorCheck'))} · ${E(m.license_code||'')}</b><span>${[m.captured_at?E(t('photo.taken',{v:m.captured_at})):'',E(m.caption||t('photo.caption')),E(m.changes||''),m.last_rights_sync_at?E(t('photo.rightsChecked',{v:String(m.last_rights_sync_at).slice(0,10)})):''].filter(Boolean).join(' · ')}</span><span class="figure-links">${link(m.source_url,t('photo.original'))}${link(m.license_url,t('photo.terms'))}</span></figcaption></figure>`}

function syncedPhotoNote(p){if(!p.image)return E(t('photo.noP18'));const s=window.AOLGlobal?.imageStatus?.(p.place_id);if(s?.state==='blocked')return E(t('photo.blocked',{reasons:s.reasons.map(r=>{const k='reason.'+r,v=t(k);return v===k?r:v}).join(', ')}));return E((s?.state==='pending'?t('photo.checking')+' ':'')+t('photo.rule'))}
// A place from the 6-hourly Wikidata sync: only what Wikidata publishes, with its source; no hours, fees or programmes.
function syncedDetail(p){const id=E(p.place_id),qid=p.wikidata||p.place_id.slice(3),c=C.coords(p),osm=c?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:'',gallery=mediaFor(p),cats=[...new Set((p.categories?.length?p.categories:[p.primary_category]).map(k=>category({primary_category:k})))],at=window.AOL_GLOBAL?.fetchedAt,sim=similarSection(p),other=uiLang()==='en'?p.name_kr:p.name_en;return `<div class="detail">${detailHero(p)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E(category(p))}${regionText(p)?' · '+E(regionText(p)):''}</p><h1><bdi>${E(nm(p))}</bdi></h1>${other&&other!==nm(p)?`<p class="detail-sub"><bdi>${E(other)}</bdi></p>`:''}<div class="detail-pills">${badge(p)}</div></header>${quickActions(p,osm)}${sectionTabs(!!sim,!!p.short_description)}${p.short_description?`<div class="detail-lead" id="detailAbout"><p class="detail-description">${E(p.short_description)}</p></div>`:''}<aside class="detail-aside" id="detailInfo"><div class="info-card synced-info"><h2>${E(t('synced.title'))}</h2><dl class="kv-list"><div class="kv"><dt>${E(t('synced.type'))}</dt><dd>${E(cats.join(' · '))}</dd></div><div class="kv"><dt>${E(t('project.where'))}</dt><dd>${E(regionText(p)||t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('project.coords'))}</dt><dd>${c?`<span class="tnum">${E(c[0].toFixed(5)+', '+c[1].toFixed(5))}</span> · ${E(t('legend.wikidata'))}`+link(osm,t('project.osm')):E(t('common.unknown'))}</dd></div><div class="kv"><dt>${E(t('project.website'))}</dt><dd>${p.website?link(p.website,t('project.open')):E(t('synced.noWebsite'))}</dd></div><div class="kv"><dt>${E(t('tab.sources'))}</dt><dd>${link('https://www.wikidata.org/wiki/'+qid,'Wikidata '+qid)}</dd></div></dl><div class="info-actions"><button class="button large" data-add-route="${id}">${I('plus')}${E(t('detail.addCourse'))}</button></div></div><div class="notice warning synced-note">${I('info')}<span>${E(t('synced.note'))}</span></div><p class="aside-note">${at?E(t('sync.every6h',{time:syncTime(at)}))+'. ':''}${E(t('synced.aside'))}</p>${dataStatus(p)}</aside><div class="detail-main"><section class="detail-section" id="detailPhotos"><h2>${E(t('photos.title'))}</h2>${gallery.length?`<div class="image-gallery">${gallery.map(m=>figureHTML(p,m)).join('')}</div>`:`<p class="section-note" id="syncedPhotoStatus">${syncedPhotoNote(p)}</p>`}<p class="section-note">${E(t('photos.reportLead'))} <a href="./support.html">${E(t('photos.report'))}</a></p></section>${archiveSections(p)}${visitsSection(p)}</div></div>${sim}</div>${actionBar(p,osm)}</div>`}

// The map shows exactly the explore results that have usable coordinates (X.mappable); the list under it, its count
// and the pins come from this one list (pinned in qa/archive.spec.mjs).
function mapProjects(){return results().filter(X.mappable)}
function mapLegend(){return `<div class="map-legend" role="group" aria-label="${E(t('legend.label'))}"><span class="legend-item"><span class="legend-mark pin" aria-hidden="true"></span>${E(t('legend.verified'))}</span><span class="legend-item"><span class="legend-mark wd" aria-hidden="true"></span>${E(t('legend.wikidata'))}</span><span class="legend-item"><span class="legend-mark src" aria-hidden="true"></span>${E(t('legend.source'))}</span><details class="legend-rule"><summary>${E(t('legend.rule'))}</summary><p>${E(t('legend.ruleText'))}</p></details></div>`}


function mapResultHTML(bounds,all=mapProjects()){const n={verified:0,wikidata:0,source:0};for(const p of all)n[X.coordKind(p)]++;const ps=bounds?all.filter(p=>bounds.contains([p.latitude,p.longitude])):all,shown=ps.slice(0,showCount),off=results().length-all.length;return `<div class="result-meta"><b>${E(bounds?t('map.here'):whereLabel())} · ${E(t('results.count',{n:fmt(ps.length)}))}</b><span>${E(t('map.counts',{v:fmt(n.verified),w:fmt(n.wikidata)}))}${n.source?E(t('map.countsSource',{n:fmt(n.source)})):''}</span>${off?`<span class="map-off">${E(t('map.offMap',{n:fmt(off)}))} <a class="text-link" href="#explore">${E(t('map.toList'))}</a></span>`:''}</div>${mapLegend()}${shown.map(p=>{const k=X.coordKind(p);return `<button class="map-list-item" data-map-select="${E(p.place_id)}"><span class="map-item-icon${COORD_CLASS[k]}">${I(catIcon(p))}</span><span class="map-item-text"><b>${E(nm(p))}</b><small>${E([category(p),regionText(p)].filter(Boolean).join(' · '))}</small><small class="coord-tag">${E(t('coord.'+k))}</small></span>${I('caret-right','map-item-caret')}</button>`}).join('')||empty(t('map.emptyTitle'),t('map.emptyBody'))}${ps.length>shown.length?`<button class="button subtle more-button" data-more>${E(t('results.more',{n:fmt(Math.min(PAGE,ps.length-shown.length))}))}</button>`:''}`}

function updateMapList(all){const el=$('#mapResults');if(el)el.innerHTML=mapResultHTML(currentMap?.getBounds(),all)}
// Editorially verified coordinates are pins; coordinates published on Wikidata (filled) or by a collected source (rings)
// are small circles drawn on the map's one canvas renderer (thousands stay fast) and their popup names the source. Markers are rebuilt only when the list of
// places changed (typing is debounced; a background update that changes nothing on the map keeps them).
function updateMapResults(){clearTimeout(mapTimer);mapTimer=null;if(!$('#mapResults'))return;const ps=mapProjects();updateMapList(ps);refreshFilters();if(!currentMap||!mapLayer)return;if(ps.length===mapShown.length&&ps.every((p,i)=>p===mapShown[i]))return;mapShown=ps;mapLayer.clearLayers();mapMarkers=[];for(const p of ps){const k=X.coordKind(p),host=(()=>{try{return new URL(p.coordinate_source_url).host}catch{return ''}})(),pop=`<div class="map-pop"><p class="map-pop-eyebrow">${E(category(p))}</p><a href="#place/${E(p.place_id)}"><b>${E(nm(p))}</b> ${E(t('pop.details'))}${I('caret-right','icon-sm')}</a>${regionText(p)?`<small>${E(regionText(p))}</small>`:''}<small class="map-pop-source">${E(t('pop.'+k,{host}))}</small></div>`;const m=k==='verified'?L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'map-pin',html:`<span class="pin-body">${I(catIcon(p))}</span>`,iconSize:[36,36],iconAnchor:[18,18],popupAnchor:[0,-16]}),title:nm(p)}).bindPopup(pop):L.circleMarker([p.latitude,p.longitude],k==='wikidata'?{renderer:mapRenderer,radius:7,weight:2,color:'#FFFFFF',fillColor:'#6B52DE',fillOpacity:1}:{renderer:mapRenderer,radius:7,weight:3,color:'#6B52DE',fillColor:'#FFFFFF',fillOpacity:1}).bindPopup(pop);m.aolId=p.place_id;m.aolSource=k;mapLayer.addLayer(m);mapMarkers.push(m)}}

async function privatePhotos(visitId){if(!window.AOLCloud?.state.user){toast(t('private.signIn'));return}const uid=window.AOLCloud.state.user.id,el=modal(t('private.title'),`<p class="muted">${E(t('private.body'))}</p><input id="privatePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" aria-label="${E(t('private.pick'))}"><div id="privatePhotoStatus" role="status"></div><div id="privatePhotoList"></div>`);const status=$('#privatePhotoStatus'),list=$('#privatePhotoList');const show=async()=>{const rows=await window.AOLCloud.photos.list(visitId);if(!el.open||window.AOLCloud.state.user?.id!==uid)return;list.innerHTML=rows.map(p=>`<figure><img class="photo" src="${E(C.safeURL(p.url))}" alt="${E(t('private.alt'))}"><button class="button danger small" data-private-delete="${E(p.id)}">${E(t('private.delete'))}</button></figure>`).join('')||`<p>${E(t('private.none'))}</p>`;list.querySelectorAll('[data-private-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('private.confirm')))return;try{await window.AOLCloud.photos.remove(b.dataset.privateDelete);await show()}catch(e){status.textContent=e.message}})};$('#privatePhotoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;status.textContent=t('private.saving');try{await window.AOLCloud.photos.upload(visitId,file);await show();status.textContent=t('private.saved')}catch(e){status.textContent=e.message}e.target.value=''};try{await show()}catch(e){status.textContent=e.message}}

// One of four brand gradients per place, so a grid of places without photos does not repeat one box.
function tone(id){let h=0;for(const ch of String(id||''))h=(h*31+ch.charCodeAt(0))>>>0;return h%4}
function railNav(){return `<span class="rail-nav" hidden><button type="button" class="rail-btn" data-rail-step="-1" aria-label="${E(t('rail.prev'))}" disabled>${I('caret-left')}</button><button type="button" class="rail-btn" data-rail-step="1" aria-label="${E(t('rail.next'))}">${I('caret-right')}</button></span>`}
// Desktop rails are one row (3 or 4 cards) that scrolls sideways; the arrows show only when there is more to see.
function railState(){for(const r of document.querySelectorAll?.('.rail-scroll')||[]){const nav=r.closest('section')?.querySelector('.rail-nav');if(!nav)continue;const update=()=>{const max=r.scrollWidth-r.clientWidth;nav.hidden=max<8;const [prev,next]=nav.querySelectorAll('button');if(prev)prev.disabled=r.scrollLeft<8;if(next)next.disabled=r.scrollLeft>max-8};r.onscroll=update;update()}}
// Place page: sticky section tabs (정보 is the info card, shown next to the content on desktop) with scroll-spy.
function sectionTabs(related,about){return `<nav class="section-tabs" aria-label="${E(t('tab.label'))}">${[...(about?[['detailAbout','tab.about']]:[]),['detailInfo','tab.info'],['detailArchive','tab.archive'],['detailPhotos','tab.photos'],['detailSources','tab.sources'],['detailVisits','tab.visits'],...(related?[['detailRelated','tab.related']]:[])].map(([id,k],i)=>`<button type="button" class="${id==='detailInfo'?'tab-info':''}${i===0?' active':''}" data-scroll-to="${id}">${E(t(k))}</button>`).join('')}</nav>`}
function spyTabs(){const tabs=[...document.querySelectorAll?.('.section-tabs button')||[]].filter(b=>b.offsetParent!==null);if(!tabs.length)return;const line=(document.querySelector('.section-tabs')?.getBoundingClientRect().bottom||0)+24;let cur=tabs[0];for(const b of tabs){const el=document.getElementById(b.dataset.scrollTo);if(el&&el.getBoundingClientRect().top<=line)cur=b}if((window.innerHeight+window.scrollY)>=document.documentElement.scrollHeight-4)cur=tabs[tabs.length-1];for(const b of tabs){b.classList.toggle('active',b===cur);if(b===cur)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')}}